import {CENTER,normalizeOSM,validCoordinate} from './core.mjs';
const memory=new Map();
export const CACHE_PREFIX='alunue-refill-api-v1:';
export function getCache(key){try{const raw=localStorage.getItem(CACHE_PREFIX+key);if(raw){const x=JSON.parse(raw);if(x&&Number.isFinite(x.at)&&x.data!==undefined)return x;}}catch{}return memory.get(key)||null;}
function putCache(key,data){const x={at:Date.now(),data};memory.set(key,x);try{localStorage.setItem(CACHE_PREFIX+key,JSON.stringify(x));}catch{}return x;}
export async function request(key,url,{ttl=3600000,timeout=12000,options={},refresh=false,validate=x=>x}={}){const old=getCache(key);if(!refresh&&old&&Date.now()-old.at<ttl)return {...old,cached:true,stale:false};const abort=new AbortController(),timer=setTimeout(()=>abort.abort(),timeout);try{const r=await fetch(url,{...options,signal:abort.signal});if(!r.ok)throw Error(`Service returned HTTP ${r.status}`);const data=validate(await r.json());return {...putCache(key,data),cached:false,stale:false};}catch(error){if(old)return {...old,cached:true,stale:true,error:error.name==='AbortError'?'Service timed out':error.message};throw Error(error.name==='AbortError'?'Service timed out. Try again later.':error.message);}finally{clearTimeout(timer);}}
export function discover(refresh=false){const query='[out:json][timeout:20];(nwr["amenity"="drinking_water"](38.52,-7.98,38.63,-7.84);nwr["drinking_water"="yes"](38.52,-7.98,38.63,-7.84);nwr["shop"="supermarket"](38.52,-7.98,38.63,-7.84););out center tags;';return request('osm-evora','https://overpass-api.de/api/interpreter',{ttl:86400000,timeout:26000,refresh,options:{method:'POST',body:new URLSearchParams({data:query})},validate:j=>{if(!Array.isArray(j.elements)||j.remark)throw Error('Incomplete map response. No partial inventory accepted.');const seen=new Set();return j.elements.map(normalizeOSM).filter(p=>p&&!seen.has(p.id)&&seen.add(p.id));}});}
export function weather(){return request('weather-evora',`https://api.open-meteo.com/v1/forecast?latitude=${CENTER.lat}&longitude=${CENTER.lon}&current=temperature_2m,apparent_temperature,is_day&timezone=Europe%2FLisbon`,{ttl:1800000,validate:j=>{if(!Number.isFinite(j.current?.temperature_2m))throw Error('Weather response unavailable.');return j.current;}});}
export function sights(){return request('sights-evora','https://en.wikipedia.org/w/api.php?action=query&list=geosearch&gscoord=38.5714%7C-7.9086&gsradius=3000&gslimit=10&format=json&origin=*',{ttl:604800000,validate:j=>{if(!Array.isArray(j.query?.geosearch))throw Error('Sights response unavailable.');return j.query.geosearch.filter(x=>validCoordinate(x)).map(x=>({id:`wiki-${x.pageid}`,name:x.title,lat:x.lat,lon:x.lon,kind:'sight',status:'reference',demo:false,source:`https://en.wikipedia.org/?curid=${x.pageid}`,sourceLabel:'Wikipedia · cultural reference',opening:'Opening/access not checked',access:'No route accessibility assessment'}));}});}
